-- Employee shipped/unshipped orders | mysql
-- Generated by scripts/export-demo-sql.ts; display formatting only.
-- Ordered sample parameters: [1,0,1,0]
-- r2 project: boundary; Preserve join input scope or specialized lowering boundary
-- r1 aggregate: boundary; Preserve project input scope or specialized lowering boundary
-- r0 sort: merged; Track output ordering without a new query block
select
  `r1`.`c0` as `employee_id`,
  cast(
    cast(sum(cast(`r1`.`c1` as double)) as double) as double
  ) as `shipped`,
  cast(
    cast(sum(cast(`r1`.`c2` as double)) as double) as double
  ) as `unshipped`
from
  (
    select
      `r2`.`c0` as `c0`,
      case
        when (
          (`r2`.`c1` is not null)
          and (`r2`.`c5` is not null)
        ) then cast(? as double)
        else cast(? as double)
      end as `c1`,
      case
        when (
          (`r2`.`c1` is not null)
          and (`r2`.`c5` is null)
        ) then cast(? as double)
        else cast(? as double)
      end as `c2`
    from
      (
        select
          `r3`.`c0` as `c0`,
          `r6`.`c0` as `c1`,
          `r6`.`c1` as `c2`,
          `r6`.`c2` as `c3`,
          `r6`.`c3` as `c4`,
          `r6`.`c4` as `c5`,
          `r6`.`c5` as `c6`
        from
          (
            select
              `employees`.`employee_id` as `c0`
            from
              `employees`
          ) as `r3`
          left join (
            select
              `orders`.`order_id` as `c0`,
              `orders`.`order_date` as `c1`,
              `orders`.`customer_id` as `c2`,
              `orders`.`employee_id` as `c3`,
              `orders`.`shipped_date` as `c4`,
              cast(`orders`.`freight` as decimal(38, 10)) as `c5`
            from
              `orders`
          ) as `r6` on (`r3`.`c0` = `r6`.`c3`)
      ) as `r2`
  ) as `r1`
group by
  `r1`.`c0`
order by
  case
    when `r1`.`c0` is null then 1
    else 0
  end asc,
  `r1`.`c0` asc;
